#'
#' \code{results$pt$asDF}
#'
#' \code{as.data.frame(results$pt)}
#'
#' @export
PercentileDirect <- function(
    data,
    X,
    sp = 0) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("PercentileDirect requires jmvcore to be installed (restart may be required)")

    if ( ! missing(X)) X <- jmvcore::resolveQuo(jmvcore::enquo(X))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(X), X, NULL))


    options <- PercentileDirectOptions$new(
        X = X,
        sp = sp)

    analysis <- PercentileDirectClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

